const body = $input.first().json.body;
const errors = [];

function isObject(value) {
  return value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value);
}

function requiredText(value, field, maxLength) {
  if (typeof value !== 'string' || !value.trim()) {
    errors.push(`${field}: texto obrigatório.`);
    return;
  }

  if (value.length > maxLength) {
    errors.push(`${field}: máximo de ${maxLength} caracteres.`);
  }
}

if (!isObject(body)) {
  return [{
    json: {
      valid: false,
      request_id: null,
      http_status: 400,
      error_code: 'INVALID_REQUEST',
      errors: ['O corpo da requisição deve ser um objeto JSON.'],
    },
  }];
}

requiredText(body.request_id, 'request_id', 128);
requiredText(body.session_id, 'session_id', 128);
requiredText(body.question, 'question', 4000);

const history = body.history ?? [];

if (!Array.isArray(history) || history.length > 12) {
  errors.push('history: envie uma lista com até 12 mensagens.');
} else {
  history.forEach((message, index) => {
    if (!isObject(message)) {
      errors.push(`history[${index}]: objeto inválido.`);
      return;
    }

    if (!['user', 'assistant'].includes(message.role)) {
      errors.push(`history[${index}].role: use user ou assistant.`);
    }

    requiredText(
      message.content,
      `history[${index}].content`,
      6000,
    );
  });
}

const context = body.context;

if (!isObject(context)) {
  errors.push('context: objeto obrigatório.');
} else {
  requiredText(context.snapshot_id, 'context.snapshot_id', 256);

  if (
    typeof context.loaded_at !== 'string' ||
    !Number.isFinite(Date.parse(context.loaded_at))
  ) {
    errors.push('context.loaded_at: data inválida.');
  }

  if (!isObject(context.filters)) {
    errors.push('context.filters: objeto obrigatório.');
  }

  if (!isObject(context.metrics)) {
    errors.push('context.metrics: objeto obrigatório.');
  } else {
    const total = context.metrics.unique_interactions;

    if (!Number.isSafeInteger(total) || total < 0) {
      errors.push(
        'context.metrics.unique_interactions: inteiro não negativo obrigatório.',
      );
    }
  }

  if (!Array.isArray(context.evidence)) {
    errors.push('context.evidence: lista obrigatória.');
  } else if (context.evidence.length > 30) {
    errors.push('context.evidence: máximo de 30 evidências.');
  }

  if (
    !Array.isArray(context.limitations) ||
    context.limitations.some(value => typeof value !== 'string')
  ) {
    errors.push('context.limitations: envie uma lista de textos.');
  }
}

if (JSON.stringify(body).length > 200000) {
  errors.push('Requisição excede o limite de 200.000 caracteres.');
}

if (errors.length) {
  return [{
    json: {
      valid: false,
      request_id: typeof body.request_id === 'string'
        ? body.request_id.slice(0, 128)
        : null,
      http_status: 400,
      error_code: 'INVALID_REQUEST',
      errors,
    },
  }];
}

return [{
  json: {
    valid: true,
    request_id: body.request_id.trim(),
    session_id: body.session_id.trim(),
    question: body.question.trim(),
    history,
    context,
  },
}];

const request = $input.first().json;

// Seleciona explicitamente os campos que serão enviados ao modelo.
const analysisInput = {
  question: request.question,
  history: request.history.map(message => ({
    role: message.role,
    content: message.content,
  })),
  context: {
    snapshot_id: request.context.snapshot_id,
    loaded_at: request.context.loaded_at,
    filters: request.context.filters,
    metrics: request.context.metrics,
    evidence: request.context.evidence,
    limitations: request.context.limitations,
  },
};

return [{
  json: {
    request_id: request.request_id,
    session_id: request.session_id,
    snapshot_id: request.context.snapshot_id,
    chatInput: JSON.stringify(analysisInput),
  },
}];

const result = $input.first().json;
const request = $('Prepare Agent Input').first().json;

const answer = typeof result.output === 'string'
  ? result.output.trim()
  : '';

if (!answer) {
  return [{
    json: {
      http_status: 502,
      body: {
        request_id: request.request_id,
        status: 'error',
        error_code: 'INVALID_AGENT_RESPONSE',
        message: 'O agente não retornou uma resposta válida.',
      },
    },
  }];
}

return [{
  json: {
    http_status: 200,
    body: {
      request_id: request.request_id,
      snapshot_id: request.snapshot_id,
      status: 'success',
      answer,
    },
  },
}];

